#include <chrono>
#include <cstdint>
#include <memory>

#include <rclcpp/rclcpp.hpp>
#include <std_msgs/msg/int64.hpp>

using namespace std::chrono_literals;

class Counter : public rclcpp::Node {
 public:
  explicit Counter(const rclcpp::NodeOptions& options = rclcpp::NodeOptions()) : Node("counter", options) {
    // Keep the 10 newest messages while they can't be delivered as fast as they are published.
    publisher_ = create_publisher<std_msgs::msg::Int64>("count", rclcpp::QoS(rclcpp::KeepLast(10)));
    // Runs on the node's clock, so it follows simulation time when use_sim_time is set.
    timer_ = create_timer(1s, [this] {
      std_msgs::msg::Int64 msg;
      msg.data = next_++;
      publisher_->publish(msg);
    });
  }

 private:
  rclcpp::Publisher<std_msgs::msg::Int64>::SharedPtr publisher_;
  rclcpp::TimerBase::SharedPtr timer_;
  std::int64_t next_ = 0;
};

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<Counter>());
  rclcpp::shutdown();
}

