#include <cinttypes>
#include <cstdint>
#include <memory>
#include <optional>

#include <rclcpp/rclcpp.hpp>
#include <std_msgs/msg/int64.hpp>

// Plain C++ with no ROS types, so a test reaches it without starting ROS.
class SequenceCheck {
 public:
  // Returns the number that should have come when `value` isn't one more than the last one,
  // and nothing when it is, or when `value` is the first one seen.
  [[nodiscard]] std::optional<std::int64_t> observe(std::int64_t value) {
    std::optional<std::int64_t> expected;
    if (last_ && value != *last_ + 1) expected = *last_ + 1;
    last_ = value;
    return expected;
  }

 private:
  std::optional<std::int64_t> last_;
};

class Watcher : public rclcpp::Node {
 public:
  explicit Watcher(const rclcpp::NodeOptions& options = rclcpp::NodeOptions()) : Node("watcher", options) {
    subscription_ = create_subscription<std_msgs::msg::Int64>(
        "count", rclcpp::QoS(rclcpp::KeepLast(10)), [this](const std_msgs::msg::Int64& msg) { on_count(msg.data); });
  }

 private:
  void on_count(std::int64_t value) {
    RCLCPP_INFO(get_logger(), "heard %" PRId64, value);
    if (const std::optional<std::int64_t> expected = check_.observe(value)) {
      RCLCPP_WARN(get_logger(), "expected %" PRId64 ", got %" PRId64, *expected, value);
    }
  }

  SequenceCheck check_;  // declared before the subscription, so it outlives the callback that uses it
  rclcpp::Subscription<std_msgs::msg::Int64>::SharedPtr subscription_;
};

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<Watcher>());
  rclcpp::shutdown();
}

#include <cstdint>
#include <format>
#include <iostream>
#include <optional>

class SequenceCheck {
 public:
  [[nodiscard]] std::optional<std::int64_t> observe(std::int64_t value) {
    std::optional<std::int64_t> expected;
    if (last_ && value != *last_ + 1) expected = *last_ + 1;
    last_ = value;
    return expected;
  }

 private:
  std::optional<std::int64_t> last_;
};

int main() {
  SequenceCheck check;
  for (const std::int64_t value : {0, 1, 2, 5, 6, 0, 1}) {
    const std::optional<std::int64_t> expected = check.observe(value);
    std::cout << (expected ? std::format("{}: expected {}\n", value, *expected) : std::format("{}: ok\n", value));
  }
}
